{"schema":"buzz-coding-session-transcript/v1","session":{"driver":"claude-agent-acp","instanceId":"7464daa50904b3d9","sessionId":"c6ed021c-6443-4587-8dc4-25979dcbbfc0","generation":1},"eventSeq":31,"timestamp":1789845186182,"turnId":"668b2ee3-dcec-4bcd-866e-128defa6809b","item":{"kind":"tool_result","toolId":"toolu_01JtWacFTh3HyNGXpdoKnbyD","toolName":"Read src/core/tilemap.ts","toolKind":"read","isError":false,"content":"```
1	// Tile lookup and axis-separated AABB movement against the tile grid
2	// (ARCHITECTURE.md §3.1). Out-of-bounds is solid; movers call x then y.
3	
4	import type { BoxDef, GameState, Rect, RoomState, TileChar, TileDef } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
5	import { PLAY_COLS, PLAY_ROWS, TILE } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
6	
7	export function tileAt(room: RoomState, col: number, row: number): TileChar | undefined {
8	  if (col < 0 || row < 0 || col >= PLAY_COLS || row >= PLAY_ROWS) return undefined;
9	  return room.tiles[row * PLAY_COLS + col];
10	}
11	
12	export function tileDefAt(state: GameState, col: number, row: number): TileDef | undefined {
13	  const ch = tileAt(state.room, col, row);
14	  return ch === undefined ? undefined : state.content.legend[ch];
15	}
16	
17	/** Static passability: undefined (out of bounds) is never passable. */
18	export function passableFor(def: TileDef | undefined, flier: boolean): boolean {
19	  if (!def) return false;
20	  if (def.passable === 'all') return true;
21	  if (def.passable === 'fliers') return flier;
22	  return false;
23	}
24	
25	/** True while any enemy in the room is alive (shutter tiles stay closed). */
26	export function enemiesAlive(room: RoomState): boolean {
27	  return room.entities.some((e) => e.kind === 'enemy' && e.alive);
28	}
29	
30	/** Dynamic passability: shutters open once the room has no live enemy. */
31	export function isPassable(state: GameState, col: number, row: number, flier: boolean): boolean {
32	  const def = tileDefAt(state, col, row);
33	  if (def && def.kind === 'shutter') return !enemiesAlive(state.room);
34	  return passableFor(def, flier);
35	}
36	
37	export interface MoveResult { moved: number; blocked: { col: number; row: number } | null }
38	
39	/** Tile index range overlapped by the half-open pixel span [a, a + len). */
40	function span(a: number, len: number): [number, number] {
41	  return [Math.floor(a / TILE), Math.ceil((a + len) / TILE) - 1];
42	}
43	
44	/**
45	 * Try to move `rect` by `delta` along `axis`. Returns how far it actually moved
46	 * (snapped flush against the first blocking tile) and that tile, if any.
47	 */
48	export function moveAxis(state: GameState, rect: Rect, axis: 'x' | 'y', delta: number, flier: boolean): MoveResult {
49	  if (delta === 0) return { moved: 0, blocked: null };
50	  const horizontal = axis === 'x';
51	  const pos = horizontal ? rect.x : rect.y;
52	  const size = horizontal ? rect.w : rect.h;
53	  const target = pos + delta;
54	  // Leading tile index along the movement axis after the move.
55	  const lead = delta > 0 ? Math.ceil((target + size) / TILE) - 1 : Math.floor(target / TILE);
56	  const [p0, p1] = horizontal ? span(rect.y, rect.h) : span(rect.x, rect.w);
57	  for (let p = p0; p <= p1; p++) {
58	    const col = horizontal ? lead : p;
59	    const row = horizontal ? p : lead;
60	    if (isPassable(state, col, row, flier)) continue;
61	    let moved = delta > 0 ? lead * TILE - (pos + size) : (lead + 1) * TILE - pos;
62	    moved = delta > 0 ? Math.max(0, moved) : Math.min(0, moved);
63	    return { moved, blocked: { col, row } };
64	  }
65	  return { moved: delta, blocked: null };
66	}
67	
68	/** Move an entity-like object (x, y, box) along one axis; returns the move result. */
69	export function slide(state: GameState, ent: { x: number; y: number; box: BoxDef }, axis: 'x' | 'y', delta: number, flier: boolean): MoveResult {
70	  const b = ent.box;
71	  const rect: Rect = { x: ent.x + b.ox, y: ent.y + b.oy, w: b.w, h: b.h };
72	  const res = moveAxis(state, rect, axis, delta, flier);
73	  if (axis === 'x') ent.x += res.moved;
74	  else ent.y += res.moved;
75	  return res;
76	}
```"}}

