/** True on the swing frames where the sword hitbox is live (DESIGN.md §4.4: frames 2–9). */
export function swordActive(state: GameState): boolean {
  const p = state.player;
  const s = state.content.player;
  if (p.swordTimer <= 0) return false;
  const f = s.swordSwingFrames - p.swordTimer;
  return f >= s.swordActiveStart && f < s.swordActiveStart + s.swordActiveFrames;
}

/** Sword hitbox for the current facing (present only while swinging). */
export function swordRect(state: GameState): Rect | null {
  if (!swordActive(state)) return null;
  return rectOf(state.player, state.content.player.swordBox[state.player.dir]);
}

/**
 * Take damage from a source at `from` (its centre): hp down, i-frames, knockback
 * directly away along the dominant axis, swing cancelled (DESIGN.md §4.6–4.7).
 */
export function hurtPlayer(state: GameState, damage: number, from: Vec): boolean {
  const p = state.player;
  const s = state.content.player;
  if (p.invuln > 0 || p.hp <= 0) return false;
  p.hp = Math.max(0, p.hp - damage);
  p.invuln = s.invulnFrames;
  const away = dirToward(from, centre(rectOf(p, p.box)), opposite(p.dir));
  const v = dirVec(away);
  p.knock = { dx: v.x * s.knockbackSpeed, dy: v.y * s.knockbackSpeed, frames: s.knockbackFrames };
  p.swordTimer = 0;
  return true;
}
