    s.progress['door:dg:1,1:8,0'] = true;
    s.progress['door:dg:1,0:7,10'] = true;
    s.progress['door:dg:1,0:8,10'] = true;
    enterRoom(s, 'dg:1,0', 12, 8); // under the boss (boss sprite x 192, box 196..220)
