    s.player.x = 200; // up sword box: 204..212 × (y-12)..(y+4)
    s.player.y = 140;
    s.player.dir = 'up';
    const boss = enemiesOf(s)[0]!;
    expect(boss.type).toBe('gnarl');
    // Swing whenever the sword is ready until the boss is dying (cap 900 frames).
    let frames = 0;
    while (boss.ai.phase !== 'dying' && frames < 900) {
