    expect(pickupsOf(s).map((p) => p.item)).toEqual(['heart']);
    expect(isPassable(s, 15, 4, false)).toBe(true);
    expect(holdUntil(s, { left: true }, (st) => st.player.x <= 120, 80)).toBeGreaterThan(0);
    expect(holdUntil(s, { down: true }, (st) => st.mode.kind === 'transition', 40)).toBeGreaterThan(0);
    hold(s, {}, 32);
    expect(holdUntil(s, { up: true }, (st) => st.mode.kind === 'transition', 40)).toBeGreaterThan(0);
    hold(s, {}, 32);
    expect(s.room.id).toBe('dg:1,0');
    expect(enemiesOf(s)).toHaveLength(0);
    expect(pickupsOf(s)).toHaveLength(0);
    expect(isPassable(s, 15, 5, false)).toBe(true);
  });
});
