1	// Entry point: fixed 60 Hz step with an accumulator, render on animation
2	// frame, and the `window.__game` debug handle (ARCHITECTURE.md §6).
3	
4	import { content } from '.[elided private context: 10 bytes, sha256:eb23d0ee3d011211e8cf40796090faa8a5103b1aab04c315811836c579d31c1d]';
5	import { createState, enterRoom, NONE } from '.[elided private context: 13 bytes, sha256:96e3c73ac27a2c7fe6ca48bf7a66da56061bd62adb7046fd1b96fb8b3ebcd5c0]';
6	import { step } from '.[elided private context: 12 bytes, sha256:eaabec083b4b8a88fc46e846f5211eb702eea4520c3efa9457c8901e1e71e006]';
7	import type { GameHandle, Input } from '.[elided private context: 13 bytes, sha256:1a908798718596940e062a9bc819e8c52b2a88328d8a328923d4f4880c1c85af]';
8	import { createKeyboard } from '.[elided private context: 17 bytes, sha256:666e339b2655f5311aaa377609ce252cec9455cda1d93a659937c9faeb4bc3d2]';
9	import { createRenderer } from '.[elided private context: 16 bytes, sha256:2c3cc8d5e4228e23132887d0373ab22f2c68bc147f21cad789d2d8a32c632b46]';
10	
11	export const VERSION = 'slice-d';
12	
13	declare global {
14	  interface Window {
15	    __game?: GameHandle;
16	  }
17	}
18	
19	function boot(): void {
20	  const canvas = document.getElementById('game') as HTMLCanvasElement | null;
21	  if (!canvas) throw new Error('canvas#game not found');
22	  const renderer = createRenderer(canvas, content);
23	  const fit = (): void => {
24	    renderer.fit(window.innerWidth, window.innerHeight);
25	  };
26	  fit();
27	  window.addEventListener('resize', fit);
28	
29	  const keyboard = createKeyboard();
30	  keyboard.attach(window);
31	
32	  // The seed is the only place time enters; the core sees a number.
33	  const state = createState(content, Date.now() >>> 0);
34	
35	  const STEP = 1000 / 60;
36	  let acc = 0;
37	  let last = performance.now();
38	  let running = true;
39	  function frame(now: number): void {
40	    acc += Math.min(now - last, 100); // cap: no spiral after a tab switch
41	    last = now;
42	    while (acc >= STEP) {
43	      if (running) step(state, keyboard.snapshot());
44	      acc -= STEP;
45	    }
46	    renderer.render(state);
47	    requestAnimationFrame(frame);
48	  }
49	
50	  const handle: GameHandle & { pause(on: boolean): void; record(on: boolean): void; reset(seed: number): void } = {
51	    version: VERSION,
52	    state,
53	    step(input?: Partial<Input>) {
54	      step(state, { ...NONE, ...input });
55	    },
56	    setInput(input) {
57	      keyboard.override(Object.keys(input).length ? input : null);
58	    },
59	    loadRoom(id, col, row) {
60	      enterRoom(state, id, col, row);
61	      state.mode = { kind: 'playing' };
62	    },
63	    pause(on) {
64	      running = !on;
65	    },
66	    record(on) {
67	      keyboard.record(on);
68	    },
69	    reset(seed) {
70	      // Fresh title-screen state under a known seed, in place so `state` stays live.
71	      Object.assign(state, createState(content, seed));
72	    },
73	  };
74	  window.__game = handle;
75	  requestAnimationFrame(frame);
76	}
77	
78	boot();
