1	// Room parsing and whole-content validation (ARCHITECTURE.md §4). Every
2	// error names the room / sprite and the offending position.
3	
4	import type { BoxDef, Content, RoomDef, TileChar, TileLegend } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
5	import { PLAY_COLS, PLAY_ROWS } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
6	
7	export function parseRoom(def: RoomDef, legend: TileLegend): TileChar[] {
8	  if (def.rows.length !== PLAY_ROWS) {
9	    throw new Error(`room ${def.id}: expected ${PLAY_ROWS} rows, got ${def.rows.length}`);
10	  }
11	  const tiles: TileChar[] = [];
12	  def.rows.forEach((row, r) => {
13	    if (row.length !== PLAY_COLS) {
14	      throw new Error(`room ${def.id}: row ${r} has ${row.length} chars, expected ${PLAY_COLS}`);
15	    }
16	    for (let c = 0; c < row.length; c++) {
17	      const ch = row[c] ?? '';
18	      if (!(ch in legend)) throw new Error(`room ${def.id}: unknown tile '${ch}' at (${c},${r})`);
19	      tiles.push(ch);
20	    }
21	  });
22	  return tiles;
23	}
24	
25	function checkSpeed(where: string, speed: number): void {
26	  if (!Number.isInteger(speed * 4) || speed < 0 || speed > 4) {
27	    throw new Error(`${where}: speed ${speed} must be a multiple of 0.25 and <= 4`);
28	  }
29	}
30	
31	function checkSprite(content: Content, where: string, id: string): void {
32	  if (!content.sprites[id]) throw new Error(`${where}: missing sprite '${id}'`);
33	}
34	
35	function checkBox(where: string, box: BoxDef): void {
36	  if (box.w <= 0 || box.h <= 0) throw new Error(`${where}: box must have positive size`);
37	}
38	
39	function checkTile(content: Content, def: RoomDef, tiles: TileChar[], what: string, col: number, row: number, needPassable: boolean): void {
40	  const c = Math.floor(col);
41	  const r = Math.floor(row);
42	  if (c < 0 || r < 0 || c >= PLAY_COLS || r >= PLAY_ROWS || !Number.isFinite(col) || !Number.isFinite(row)) {
43	    throw new Error(`room ${def.id}: ${what} at (${col},${row}) is outside the field`);
44	  }
45	  if (!needPassable) return;
46	  const ch = tiles[r * PLAY_COLS + c] ?? '';
47	  const tile = content.legend[ch];
48	  if (!tile || tile.passable === 'none') {
49	    throw new Error(`room ${def.id}: ${what} at (${col},${row}) is on impassable tile '${ch}'`);
50	  }
51	}
52	
53	export function validateContent(content: Content): void {
54	  const legendDefs = Object.values(content.legend);
55	  if (legendDefs.filter((t) => t.kind === 'door').length !== 1) throw new Error('legend: exactly one door tile required');
56	  if (legendDefs.filter((t) => t.kind === 'lockedDoor').length > 1) throw new Error('legend: at most one lockedDoor tile');
57	  for (const t of legendDefs) checkSprite(content, `tile '${t.char}'`, t.sprite);
58	
59	  for (const [char, colour] of Object.entries(content.palette)) {
60	    if (!/^#[0-9a-fA-F]{6}$/.test(colour)) throw new Error(`palette '${char}': bad colour ${colour}`);
61	  }
62	  for (const [id, sprite] of Object.entries(content.sprites)) {
63	    const w = sprite.rows[0]?.length ?? 0;
64	    if (w === 0 || sprite.rows.length === 0) throw new Error(`sprite ${id}: empty`);
65	    sprite.rows.forEach((row, y) => {
66	      if (row.length !== w) throw new Error(`sprite ${id}: row ${y} width ${row.length} != ${w}`);
67	      for (const ch of row) {
68	        if (ch !== '.' && !(ch in content.palette)) throw new Error(`sprite ${id}: row ${y} char '${ch}' not in palette`);
69	      }
70	    });
71	  }
72	
73	  for (const def of Object.values(content.rooms)) {
74	    const tiles = parseRoom(def, content.legend);
75	    for (const [dir, id] of Object.entries(def.neighbors)) {
76	      if (!content.rooms[id]) throw new Error(`room ${def.id}: neighbour ${dir} '${id}' does not exist`);
77	    }
78	    for (const s of def.spawns) {
79	      if (!content.enemies[s.kind]) throw new Error(`room ${def.id}: unknown enemy kind '${s.kind}'`);
80	      checkTile(content, def, tiles, `spawn ${s.kind}`, s.col, s.row, true);
81	    }
82	    for (const it of def.items) checkTile(content, def, tiles, `item ${it.item}`, it.col, it.row, true);
83	    for (const w of def.warps) {
84	      checkTile(content, def, tiles, 'warp', w.col, w.row, true);
85	      const to = content.rooms[w.to];
86	      if (!to) throw new Error(`room ${def.id}: warp at (${w.col},${w.row}) targets missing room '${w.to}'`);
87	      checkTile(content, to, parseRoom(to, content.legend), `warp target from ${def.id}`, w.toCol, w.toRow, true);
88	    }
89	  }
90	  if (!content.rooms[content.start.room]) throw new Error(`start room '${content.start.room}' does not exist`);
91	
92	  const p = content.player;
93	  checkSpeed('player', p.speed);
94	  checkSpeed('player knockback', p.knockbackSpeed);
95	  checkBox('player', p.box);
96	  for (const d of ['up', 'down', 'left', 'right'] as const) {
97	    checkSprite(content, 'player', `${p.sprite}-${d}`);
98	  }
99	  for (const e of Object.values(content.enemies)) {
100	    const where = `enemy ${e.kind}`;
101	    checkSpeed(where, e.speed);
102	    if (e.chase) checkSpeed(`${where} chase`, e.chase.speed);
103	    checkBox(where, e.box);
104	    checkSprite(content, where, e.sprite);
105	    if (e.altSprite) checkSprite(content, where, e.altSprite);
106	    if (e.projectile) {
107	      checkSpeed(`${where} projectile`, e.projectile.speed);
108	      checkSprite(content, `${where} projectile`, e.projectile.sprite);
109	    }
110	    if (e.drops.heart + e.drops.rupee > 100) throw new Error(`${where}: drop chances exceed 100`);
111	    if (e.timing.moveMin > e.timing.moveMax || e.timing.pauseMin > e.timing.pauseMax) {
112	      throw new Error(`${where}: timing min > max`);
113	    }
114	  }
115	}
