17	/** Largest integer scale at which 256×240 fits inside the given box. */
18	export function integerScale(boxWidth: number, boxHeight: number): number {
19	  return Math.max(1, Math.floor(Math.min(boxWidth / SCREEN_W, boxHeight / SCREEN_H)));
