30	  const sprites = createSpriteCache(content, canvas.ownerDocument);
31	
32	  function fit(boxWidth: number, boxHeight: number): number {
33	    const k = integerScale(boxWidth, boxHeight);
34	    canvas.style.width = `${SCREEN_W * k}px`;
35	    canvas.style.height = `${SCREEN_H * k}px`;
36	    return k;
37	  }
