40	    ctx.fillStyle = '#000000';
41	    ctx.fillRect(0, 0, SCREEN_W, SCREEN_H);
42	    drawHud(ctx, state, sprites);
43	    ctx.save();
44	    ctx.translate(0, HUD_H);
45	    ctx.beginPath();
46	    ctx.rect(0, 0, PLAY_W, PLAY_H);
47	    ctx.clip();
48	    if (state.mode.kind !== 'title' && state.mode.kind !== 'gameover' && state.mode.kind !== 'win') {
49	      drawField(ctx, state, sprites);
50	    }
