10	/** The warp under the player's body centre, if that tile is a stairs tile with one. */
11	export function checkWarp(state: GameState): WarpDef | null {
12	  const c = centre(rectOf(state.player, state.player.box));
13	  const col = Math.floor(c.x / TILE);
14	  const row = Math.floor(c.y / TILE);
15	  const ch = tileAt(state.room, col, row);
16	  const def = ch === undefined ? undefined : state.content.legend[ch];
17	  if (!def || def.kind !== 'stairs') return null;
18	  const room = state.content.rooms[state.room.id];
19	  return room?.warps.find((w) => w.col === col && w.row === row) ?? null;
20	}
21	
22	/** Big items freeze the world in a 60-frame hold pose (DESIGN.md §5.3). */
23	export function isHoldItem(item: ItemKind): boolean {
24	  return item === 'sword' || item === 'heartContainer' || item === 'artifact';
25	}
26	
27	export function applyPickup(state: GameState, item: ItemKind): void {
28	  const p = state.player;
29	  const inv = state.inventory;
30	  switch (item) {
31	    case 'sword': inv.sword = true; break;
32	    case 'key': inv.keys++; break;
33	    case 'heart': p.hp = Math.min(p.hp + 2, p.maxHp); break;
34	    case 'heartContainer':
35	      p.maxHp = Math.min(p.maxHp + 2, state.content.player.maxHpCap);
36	      p.hp = p.maxHp;
37	      break;
38	    case 'rupee': inv.rupees = Math.min(inv.rupees + 1, 255); break;
39	    case 'artifact': inv.artifact = true; break;
40	  }
41	}
42	
43	/** Pick up every live pickup overlapping the body (even with i-frames). */
44	export function collectPickups(state: GameState): void {
45	  const body = rectOf(state.player, state.player.box);
46	  for (const e of state.room.entities) {
47	    if (e.kind !== 'pickup' || !e.alive) continue;
48	    if (!overlaps(body, rectOf(e, e.box))) continue;
49	    takePickup(state, e);
50	    if (state.mode.kind !== 'playing') return;
51	  }
52	}
53	
54	function takePickup(state: GameState, pickup: Pickup): void {
55	  pickup.alive = false;
56	  if (pickup.persistKey) state.progress[pickup.persistKey] = true;
57	  applyPickup(state, pickup.item);
58	  if (isHoldItem(pickup.item)) {
59	    state.player.swordTimer = 0;
60	    state.player.knock = null;
61	    state.player.moving = false;
62	    state.mode = { kind: 'hold', item: pickup.item, timer: state.content.timings.holdFrames };
63	  }
64	}
65	
66	function mirrored(col: number, row: number): { dir: Dir; col: number; row: number } | null {
67	  if (row === 0) return { dir: 'up', col, row: PLAY_ROWS - 1 };
68	  if (row === PLAY_ROWS - 1) return { dir: 'down', col, row: 0 };
69	  if (col === 0) return { dir: 'left', col: PLAY_COLS - 1, row };
70	  if (col === PLAY_COLS - 1) return { dir: 'right', col: 0, row };
71	  return null;
72	}
73	
74	function isLocked(state: GameState, col: number, row: number): boolean {
75	  const ch = tileAt(state.room, col, row);
76	  return ch !== undefined && state.content.legend[ch]?.kind === 'lockedDoor';
77	}
78	
79	/**
80	 * The player was blocked by (col,row) this frame: if it is a locked door and a
81	 * key is held, open the whole (two-tile) door here and on the neighbour's side.
82	 */
83	export function tryUnlockDoor(state: GameState, blocked: { col: number; row: number }): boolean {
84	  if (!isLocked(state, blocked.col, blocked.row) || state.inventory.keys <= 0) return false;
85	  state.inventory.keys--;
86	  const open = doorChar(state.content);
87	  const cells = [blocked, ...[[1, 0], [-1, 0], [0, 1], [0, -1]]
88	    .map(([dc, dr]) => ({ col: blocked.col + (dc ?? 0), row: blocked.row + (dr ?? 0) }))
89	    .filter((c) => isLocked(state, c.col, c.row))];
90	  const roomId = state.room.id;
91	  for (const c of cells) {
92	    state.room.tiles[c.row * PLAY_COLS + c.col] = open;
93	    state.progress[`door:${roomId}:${c.col},${c.row}`] = true;
94	    const m = mirrored(c.col, c.row);
95	    const other = m ? state.content.rooms[roomId]?.neighbors[m.dir] : undefined;
96	    if (m && other) state.progress[`door:${other}:${m.col},${m.row}`] = true;
97	  }
98	  return true;
99	}
