// Entry point. For the scaffold this draws a static placeholder room:
// a 64px HUD band on top and a 16x11 grid of 16x16 tiles with a border.
// The real game loop replaces `drawPlaceholder` once the core exists.

import {
  createScreen,
  HUD_HEIGHT,
  NES_HEIGHT,
  NES_WIDTH,
  ROOM_COLS,
  ROOM_ROWS,
  TILE,
  type Screen,
} from '.[elided private context: 16 bytes, sha256:2c3cc8d5e4228e23132887d0373ab22f2c68bc147f21cad789d2d8a32c632b46]';

interface GameDebugHandle {
  readonly version: string;
}

declare global {
  interface Window {
    __game?: GameDebugHandle;
  }
}

const PALETTE = {
  hud: '#000000',
  hudText: '#fcfcfc',
  floor: '#d8b878', // sandy overworld floor
  wall: '#00a800', // green border tiles
  wallDark: '#005800',
} as const;

function drawHud(ctx: CanvasRenderingContext2D): void {
  ctx.fillStyle = PALETTE.hud;
  ctx.fillRect(0, 0, NES_WIDTH, HUD_HEIGHT);
  // Three placeholder hearts and a label, so the band is visibly a HUD.
  ctx.fillStyle = '#f83800';
  for (let i = 0; i < 3; i++) {
    ctx.fillRect(176 + i * 10, 40, 8, 8);
  }
  ctx.fillStyle = PALETTE.hudText;
  ctx.font = '8px monospace';
  ctx.textBaseline = 'top';
  ctx.fillText('-LIFE-', 176, 28);
  ctx.fillText('TINY LEGEND', 16, 28);
}

function drawTile(ctx: CanvasRenderingContext2D, col: number, row: number, kind: 'floor' | 'wall'): void {
  const x = col * TILE;
  const y = HUD_HEIGHT + row * TILE;
  if (kind === 'floor') {
    ctx.fillStyle = PALETTE.floor;
    ctx.fillRect(x, y, TILE, TILE);
    return;
  }
  // Wall: a 2-tone block so the border reads as tiles, not a flat band.
  ctx.fillStyle = PALETTE.wall;
  ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = PALETTE.wallDark;
  ctx.fillRect(x + 2, y + 2, TILE - 4, TILE - 4);
  ctx.fillStyle = PALETTE.wall;
  ctx.fillRect(x + 6, y + 6, 4, 4);
}

function drawRoom(ctx: CanvasRenderingContext2D): void {
  for (let row = 0; row < ROOM_ROWS; row++) {
    for (let col = 0; col < ROOM_COLS; col++) {
      const onEdge = row === 0 || row === ROOM_ROWS - 1 || col === 0 || col === ROOM_COLS - 1;
      // Leave a doorway gap in the middle of each edge, Zelda-style.
      const midCol = col === 7 || col === 8;
      const midRow = row === 5;
      const doorway = onEdge && ((row === 0 || row === ROOM_ROWS - 1) ? midCol : midRow);
      drawTile(ctx, col, row, onEdge && !doorway ? 'wall' : 'floor');
    }
  }
}

function drawPlaceholder(screen: Screen): void {
  const { ctx } = screen;
  ctx.clearRect(0, 0, NES_WIDTH, NES_HEIGHT);
  drawHud(ctx);
  drawRoom(ctx);
}

function boot(): void {
  const screen = createScreen();
  drawPlaceholder(screen);
  window.__game = { version: 'scaffold' };
}

