// Canvas setup for the NES-sized virtual screen.
//
// The canvas keeps its 256x240 backing store; only its CSS size changes,
// always to an integer multiple so pixels stay crisp. The black letterbox
// comes from the page background (see index.html).

export const NES_WIDTH = 256;
export const NES_HEIGHT = 240;
export const TILE = 16;
export const HUD_HEIGHT = 64;
export const ROOM_COLS = NES_WIDTH / TILE; // 16
export const ROOM_ROWS = (NES_HEIGHT - HUD_HEIGHT) / TILE; // 11

export interface Screen {
  readonly canvas: HTMLCanvasElement;
  readonly ctx: CanvasRenderingContext2D;
  /** Current integer CSS scale factor. */
  scale: number;
}

/** Largest integer scale at which 256x240 fits inside the given box. */
export function integerScale(boxWidth: number, boxHeight: number): number {
  const s = Math.floor(Math.min(boxWidth / NES_WIDTH, boxHeight / NES_HEIGHT));
  return Math.max(1, s);
}

/** Apply an integer CSS scale so the canvas fits the window. */
export function fitToWindow(screen: Screen): void {
  const scale = integerScale(window.innerWidth, window.innerHeight);
  screen.scale = scale;
  screen.canvas.style.width = `${NES_WIDTH * scale}px`;
  screen.canvas.style.height = `${NES_HEIGHT * scale}px`;
}

/**
 * Find (or create) the game canvas, size it to NES resolution, and keep it
 * integer-scaled to the window. Returns the canvas and its 2D context.
 */
export function createScreen(doc: Document = document): Screen {
  let canvas = doc.getElementById('game') as HTMLCanvasElement | null;
  if (!canvas) {
    canvas = doc.createElement('canvas');
    canvas.id = 'game';
    doc.body.appendChild(canvas);
  }
  canvas.width = NES_WIDTH;
  canvas.height = NES_HEIGHT;
  canvas.style.imageRendering = 'pixelated';

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas context unavailable');
  ctx.imageSmoothingEnabled = false;

  const screen: Screen = { canvas, ctx, scale: 1 };
  fitToWindow(screen);
  window.addEventListener('resize', () => fitToWindow(screen));
  return screen;
}
