import { expect, test, type Page } from '@playwright/test';

// Attack list 21 (browser half): window resize to tiny / huge, tab blur
// mid-swing, OS key repeat, and sub-frame key taps. Run with:
//   pnpm exec playwright test -c tests/poke/playwright.poke.config.ts

interface Handle {
  state: { mode: { kind: string }; frame: number; player: { x: number; y: number; swordTimer: number }; inventory: { sword: boolean } };
  step(input?: Record<string, boolean>): void;
  pause(on: boolean): void;
  reset(seed: number): void;
  loadRoom(id: string, col?: number, row?: number): void;
}

async function ready(page: Page): Promise<void> {
  await page.goto('/');
  await page.waitForFunction(() => window.__game !== undefined);
}

/** A human-length tap: the key is held across several 60 Hz samples. */
async function tap(page: Page, key: string, holdMs = 50): Promise<void> {
  await page.keyboard.down(key);
  await page.waitForTimeout(holdMs);
  await page.keyboard.up(key);
}

async function startGame(page: Page): Promise<void> {
  await page.waitForFunction(() => (window.__game?.state.frame ?? 0) > 20);
  await tap(page, 'Enter');
  await page.waitForFunction(() => window.__game?.state.mode.kind === 'playing');
}

async function mode(page: Page): Promise<string> {
  return page.evaluate(() => window.__game!.state.mode.kind);
}

async function canvasBox(page: Page): Promise<{ w: number; h: number; rendering: string }> {
  return page.evaluate(() => {
    const c = document.getElementById('game') as HTMLCanvasElement;
    const r = c.getBoundingClientRect();
    return { w: r.width, h: r.height, rendering: getComputedStyle(c).imageRendering };
  });
}

test('tiny window: scale stays 1 (canvas 256×240 CSS px, pixelated)', async ({ page }) => {
  await ready(page);
  await page.setViewportSize({ width: 120, height: 90 });
  await page.waitForTimeout(50);
  const box = await canvasBox(page);
  expect(box.w).toBe(256);
  expect(box.h).toBe(240);
  expect(box.rendering).toBe('pixelated');
});

test('huge window: integer scale, no fractional CSS size', async ({ page }) => {
  await ready(page);
  await page.setViewportSize({ width: 3000, height: 2000 });
  await page.waitForTimeout(50);
  const box = await canvasBox(page);
  const k = Math.min(Math.floor(3000 / 256), Math.floor(2000 / 240));
  expect(box.w).toBe(256 * k);
  expect(box.h).toBe(240 * k);
  expect(k).toBe(8);
  await page.setViewportSize({ width: 700, height: 500 });
  await page.waitForTimeout(50);
  const box2 = await canvasBox(page);
  expect([box2.w, box2.h]).toEqual([512, 480]);
});

test('tab blur mid-swing releases every key: the walk stops and the swing finishes on its own', async ({ page }) => {
  await ready(page);
  await startGame(page);
  await page.evaluate(() => {
    (window.__game as unknown as Handle).state.inventory.sword = true;
  });
  await page.keyboard.down('ArrowRight');
  await page.waitForTimeout(150);
  await page.keyboard.down('KeyZ');
  await page.waitForTimeout(40);
