    const g = window.__game as unknown as Handle;
    return { x: g.state.player.x, swinging: g.state.player.swordTimer > 0 };
  });
  expect(mid.swinging).toBe(true);
  // The tab loses focus while both keys are physically held: no keyup will ever arrive.
  await page.evaluate(() => window.dispatchEvent(new Event('blur')));
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => {
    const g = window.__game as unknown as Handle;
    return { x: g.state.player.x, swordTimer: g.state.player.swordTimer, mode: g.state.mode.kind };
  });
  expect(after.swordTimer).toBe(0);
  expect(after.mode).toBe('playing');
  await page.waitForTimeout(200);
  const later = await page.evaluate(() => (window.__game as unknown as Handle).state.player.x);
  expect(later).toBe(after.x); // no movement: blur released the keys
  await page.keyboard.up('ArrowRight');
  await page.keyboard.up('KeyZ');
});

test('OS key repeat: 30 repeated keydowns on Z produce exactly one swing', async ({ page }) => {
  await ready(page);
  await startGame(page);
  await page.evaluate(() => {
    const g = window.__game as unknown as Handle;
    g.state.inventory.sword = true;
    (window as unknown as { __swings: number }).__swings = 0;
    let prev = 0;
    setInterval(() => {
      const t = g.state.player.swordTimer;
      if (t === 12 && prev !== 12) (window as unknown as { __swings: number }).__swings++;
      prev = t;
    }, 1);
  });
  // Playwright marks every keyboard.down after the first as repeat=true, like the OS auto-repeat.
  for (let i = 0; i < 30; i++) {
    await page.keyboard.down('KeyZ');
    await page.waitForTimeout(20);
  }
  await page.waitForTimeout(300);
  await page.keyboard.up('KeyZ');
  const swings = await page.evaluate(() => (window as unknown as { __swings: number }).__swings);
  expect(swings).toBe(1);
});

test('held Enter taps at the title: the first starts, later ones toggle pause after the 15-frame lock', async ({ page }) => {
  await ready(page);
