6	/** Advance the RNG and return a uint32. */
7	export function nextU32(state: GameState): number {
8	  const a = (state.rng + 0x6d2b79f5) | 0;
9	  state.rng = a >>> 0;
10	  let t = a ^ (a >>> 15);
11	  t = Math.imul(t, 1 | a);
12	  t ^= t + Math.imul(t ^ (t >>> 7), 61 | t);
13	  return (t ^ (t >>> 14)) >>> 0;
14	}
