11	function makePlayer(content: Content): Player {
12	  const s = content.player;
13	  return {
14	    x: content.start.col * TILE,
15	    y: content.start.row * TILE,
16	    box: s.box,
17	    dir: 'up',
18	    hp: s.startHp,
19	    maxHp: s.startHp,
20	    invuln: 0,
21	    knock: null,
22	    swordTimer: 0,
23	    swordCooldown: 0,
24	    moving: false,
25	  };
26	}
