32	/** A fresh state on the title screen. `seed` is the whole run's randomness. */
33	export function createState(content: Content, seed: number): GameState {
34	  const state: GameState = {
35	    frame: 0,
36	    rng: seed >>> 0,
37	    mode: { kind: 'title', timer: content.timings.titleLockFrames },
38	    input: { ...NONE },
39	    prevInput: { ...NONE },
40	    player: makePlayer(content),
41	    inventory: makeInventory(),
42	    room: { id: content.start.room, tiles: [], entities: [], nextEntityId: 1 },
43	    progress: {},
44	    canContinue: false,
45	    content,
46	  };
47	  enterRoom(state, content.start.room, content.start.col, content.start.row, 'up');
48	  return state;
49	}
