51	/** Title → fresh run: everything reset except the running RNG. */
52	export function newGame(state: GameState): void {
53	  const c = state.content;
54	  state.player = makePlayer(c);
55	  state.inventory = makeInventory();
56	  state.progress = {};
57	  state.canContinue = false;
58	  enterRoom(state, c.start.room, c.start.col, c.start.row, 'up');
59	  state.mode = { kind: 'playing' };
60	}
61	
62	/** Continue after Game Over: hp refilled, maxHp/inventory/progress kept. */
63	export function respawnAfterDeath(state: GameState): void {
64	  const c = state.content;
65	  const p = state.player;
66	  p.hp = c.player.startHp;
67	  p.invuln = 0;
68	  enterRoom(state, c.start.room, c.start.col, c.start.row, 'up');
69	  state.mode = { kind: 'playing' };
