79	/**
80	 * Build the room from its definition plus progress flags and spawn its
81	 * entities. Old entities are discarded (NES respawn-on-re-entry). If col/row
82	 * are given the player is placed there (fractional col allowed, e.g. 7.5).
83	 */
84	export function enterRoom(state: GameState, id: RoomId, col?: number, row?: number, facing?: Dir): void {
85	  const c = state.content;
86	  const def = mustGet(c.rooms, id, 'room');
87	  const tiles = parseRoom(def, c.legend);
88	  const open = doorChar(c);
89	  tiles.forEach((ch, i) => {
90	    const t = c.legend[ch];
91	    if (t?.kind === 'lockedDoor' && state.progress[`door:${id}:${i % PLAY_COLS},${Math.floor(i / PLAY_COLS)}`]) {
92	      tiles[i] = open;
93	    }
94	  });
95	  state.room = { id, tiles, entities: [], nextEntityId: 1 };
96	  for (const s of def.spawns) {
97	    const stats = mustGet(c.enemies, s.kind, 'enemy kind');
98	    if (stats.behaviour === 'boss' && state.progress[`boss:${id}`]) continue;
99	    spawnEnemy(state, s.kind, s.col, s.row);
100	  }
101	  for (const it of def.items) {
102	    const key = `item:${id}:${it.col},${it.row}`;
103	    if (state.progress[key]) continue;
104	    spawnPickup(state, it.item, it.col * TILE, it.row * TILE, null, key);
105	  }
106	  const p = state.player;
107	  if (col !== undefined && row !== undefined) {
108	    p.x = col * TILE;
109	    p.y = row * TILE;
110	  }
111	  if (facing) p.dir = facing;
112	  p.knock = null;
113	  p.swordTimer = 0;
114	  p.moving = false;
115	}
