1	// The flier (Bat: Rest⇄Fly, 8-way with a speed ramp and edge reflection,
2	// ignores tiles) and the boss (Gnarl: Patrol→Windup→Spit→Recover).
3	// DESIGN.md §6.3 for behaviour, EnemyStats for numbers.
4	
5	import { enterPhase, rollTimer, tick } from '.[elided private context: 12 bytes, sha256:407d12feea36b967743d62b71e16724083ac5d7d96f41e893cc26b6d9767a1f1]';
6	import { chance, randInt } from '.[elided private context: 6 bytes, sha256:59f3dabede66a9ea6d5651c9e761f8b9ed347dafa7af4cacbee6187c60c99077]';
7	import { fire } from '.[elided private context: 14 bytes, sha256:bcdf19a2aa3ea5ff4e5051bc9c05f0d6a87fde65abd81b8d5d244c2a9ea93abd]';
8	import type { Enemy, EnemyStats, GameState, Vec } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
9	import { PLAY_H, PLAY_W } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
10	
11	const DIAG = 0.7071;
12	/** Compass directions clockwise from up. */
13	const DIR8: readonly Vec[] = [
14	  { x: 0, y: -1 }, { x: DIAG, y: -DIAG }, { x: 1, y: 0 }, { x: DIAG, y: DIAG },
15	  { x: 0, y: 1 }, { x: -DIAG, y: DIAG }, { x: -1, y: 0 }, { x: -DIAG, y: -DIAG },
16	];
17	
18	export function updateFlier(state: GameState, e: Enemy, stats: EnemyStats): void {
19	  const t = stats.timing;
20	  const f = stats.flight ?? { accel: stats.speed, turnEvery: 24, turnPct: 50 };
21	  if (e.ai.timer < 0) enterPhase(e, 'idle', rollTimer(state, t.pauseMin, t.pauseMax));
22	  switch (e.ai.phase) {
23	    case 'idle':
24	      e.vx = 0;
25	      e.vy = 0;
26	      if (tick(e)) {
27	        e.dir8 = randInt(state, 8);
28	        enterPhase(e, 'move', rollTimer(state, t.moveMin, t.moveMax));
29	      }
30	      return;
31	    case 'move': {
32	      const speed = Math.min(stats.speed, f.accel * e.phaseFrames);
33	      if (e.phaseFrames % f.turnEvery === 0 && chance(state, f.turnPct)) {
34	        e.dir8 = (e.dir8 + (chance(state, 50) ? 1 : 7)) % 8;
35	      }
36	      const v = DIR8[e.dir8] ?? DIR8[0]!;
37	      e.vx = v.x * speed;
38	      e.vy = v.y * speed;
39	      e.x += e.vx;
40	      e.y += e.vy;
41	      // Reflect off the play-area edges (the body box must stay inside).
42	      const left = e.x + e.box.ox;
43	      const top = e.y + e.box.oy;
44	      if (left < 0 || left + e.box.w > PLAY_W) {
45	        e.x = left < 0 ? -e.box.ox : PLAY_W - e.box.w - e.box.ox;
46	        e.dir8 = (8 - e.dir8) % 8;
47	      }
48	      if (top < 0 || top + e.box.h > PLAY_H) {
49	        e.y = top < 0 ? -e.box.oy : PLAY_H - e.box.h - e.box.oy;
50	        e.dir8 = (12 - e.dir8) % 8;
51	      }
52	      if (tick(e)) enterPhase(e, 'idle', rollTimer(state, t.pauseMin, t.pauseMax));
53	      return;
54	    }
55	    default:
56	      enterPhase(e, 'idle', rollTimer(state, t.pauseMin, t.pauseMax));
57	  }
58	}
59	
60	export function updateBoss(state: GameState, e: Enemy, stats: EnemyStats): void {
61	  const t = stats.timing;
62	  const b = stats.boss ?? { minY: 0, maxY: PLAY_H - 32, spitFirst: 90, spitAfter: 120, mouth: { x: 0, y: 14 } };
63	  if (e.ai.timer < 0) {
64	    e.dir = 'left';
65	    e.vy = stats.speed;
66	    e.spit = b.spitFirst;
67	    enterPhase(e, 'move', 0);
68	  }
69	  switch (e.ai.phase) {
70	    case 'move':
71	      e.y += e.vy;
72	      if (e.y <= b.minY) {
73	        e.y = b.minY;
74	        e.vy = stats.speed;
75	      } else if (e.y >= b.maxY) {
76	        e.y = b.maxY;
77	        e.vy = -stats.speed;
78	      }
79	      e.spit--;
80	      if (e.spit <= 0) enterPhase(e, 'windup', t.windup);
81	      return;
82	    case 'windup':
83	      if (tick(e)) enterPhase(e, 'attack', 1);
84	      return;
85	    case 'attack':
86	      if (stats.projectile) fire(state, { x: e.x + b.mouth.x, y: e.y + b.mouth.y }, stats.projectile, e.dir, e.id);
87	      enterPhase(e, 'cooldown', t.cooldown);
88	      return;
89	    case 'cooldown':
90	      if (tick(e)) {
91	        e.spit = b.spitAfter;
92	        enterPhase(e, 'move', 0);
93	      }
94	      return;
95	    default:
96	      enterPhase(e, 'move', 0);
97	  }
98	}
