16	export function decode(script: string): ScriptStep[] {
17	  return script.trim().split(/\s+/).map((token) => {
18	    const m = /^([udlras]*|\.)(\d+)$/.exec(token);
19	    if (!m) throw new Error(`bad token ${token}`);
20	    const input: Partial<Input> = {};
21	    for (const ch of m[1] ?? '') {
22	      const key = CODE[ch];
23	      if (key) input[key] = true;
24	    }
25	    return { frames: Number(m[2]), input };
26	  });
27	}
28	
29	interface Checkpoints {
30	  swordRoom: string | null;
31	  swordFrame: number | null;
32	  dungeonFrame: number | null;
33	  keyRoom: string | null;
34	  bossFrame: number | null;
35	  winFrame: number | null;
36	  minHp: number;
37	}
38	
39	function play(state: GameState, steps: readonly ScriptStep[]): Checkpoints {
40	  const c: Checkpoints = { swordRoom: null, swordFrame: null, dungeonFrame: null, keyRoom: null, bossFrame: null, winFrame: null, minHp: 99 };
41	  for (const s of steps) {
42	    for (let i = 0; i < s.frames; i++) {
43	      step(state, { ...NONE, ...s.input });
44	      if (state.inventory.sword && c.swordFrame === null) {
45	        c.swordFrame = state.frame;
46	        c.swordRoom = state.room.id;
47	      }
48	      if (state.room.id === 'dg:1,1' && c.dungeonFrame === null) c.dungeonFrame = state.frame;
49	      if (state.inventory.keys === 1 && c.keyRoom === null) c.keyRoom = state.room.id;
50	      if (state.progress['boss:dg:1,0'] && c.bossFrame === null) c.bossFrame = state.frame;
51	      if (state.mode.kind === 'win' && c.winFrame === null) c.winFrame = state.frame;
52	      if (state.mode.kind === 'playing') c.minHp = Math.min(c.minHp, state.player.hp);
53	    }
54	  }
55	  return c;
56	}
