// NES edge scroll as a mode (ARCHITECTURE.md §3.2, A5): the new room is built
// at once, the simulation freezes for `transitionFrames`, and the renderer
// slides both rooms. The player arrives on the opposite edge (DESIGN.md §4.3).

import { mustGet } from '.[elided private context: 7 bytes, sha256:71fee27875c7a562ff537bf33cf473e08d0c30b8515cae5617db13520949e7c7]';
import { enterRoom } from '.[elided private context: 8 bytes, sha256:b3c48a6e44465f13f51338fa32f80c7a33eea91d1b91f06ea50bfe3472a7e899]';
import type { Dir, GameState } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
import { PLAY_H, PLAY_W, TILE } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';

export function beginTransition(state: GameState, dir: Dir): void {
  const from = state.room.id;
  const to = mustGet(state.content.rooms, from, 'room').neighbors[dir];
  if (!to) throw new Error(`room ${from} has no neighbour ${dir}`);
  state.mode = {
    kind: 'transition',
    dir,
    from,
    to,
    fromTiles: state.room.tiles,
    frame: 0,
    frames: state.content.timings.transitionFrames,
  };
  enterRoom(state, to);
  const p = state.player;
  switch (dir) {
    case 'right': p.x = 0; break;
    case 'left': p.x = PLAY_W - TILE; break;
    case 'down': p.y = 0; break;
    case 'up': p.y = PLAY_H - TILE; break;
  }
  p.dir = dir;
}

export function tickTransition(state: GameState): void {
  const m = state.mode;
  if (m.kind !== 'transition') return;
  m.frame++;
  if (m.frame >= m.frames) state.mode = { kind: 'playing' };
}

/** 0..1 progress of the scroll, for the renderer. */
export function transitionProgress(state: GameState): number {
  const m = state.mode;
  return m.kind === 'transition' ? m.frame / m.frames : 1;
}
